#
# Prints the Java original's candidate list for one Latin key sequence.
#
# testdata/golden_e2e.tsv is generated by running the unmodified Java engine
# (tools/golden-java), so this is the Java answer without needing Maven or a
# JDK. Regenerating it is the slow path:
#
#   mvn -q -f tools/golden-java/pom.xml compile exec:java -Dexec.args=testdata
#
# Output is formatted like paiza_query's so the two can be compared directly.
#
#   python tools/golden_lookup.py bagsi
#   python tools/golden_lookup.py bagsi severe

import io
import os
import sys

TAB = chr(9)
NL = chr(10)

# Mongolian output must survive being redirected to a file: Python otherwise
# encodes stdout with the Windows console code page and dies on the first
# non-ASCII character, which is exactly what happens when someone pipes this
# into a file to read it in an editor that has the font.
try:
    sys.stdout.reconfigure(encoding='utf-8')
except AttributeError:  # Python < 3.7
    pass


def rows(path):
    with io.open(path, encoding='utf-8') as f:
        for line in f:
            fields = line.rstrip(NL).split(TAB)
            if len(fields) >= 4:
                yield fields


def main():
    if len(sys.argv) < 2:
        print('usage: golden_lookup.py <latin> [fuzzy|severe]')
        return 2
    word = sys.argv[1]
    mode = sys.argv[2] if len(sys.argv) > 2 else 'fuzzy'

    here = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    path = os.path.join(here, 'testdata', 'golden_e2e.tsv')
    if not os.path.exists(path):
        print('missing ' + path)
        return 1

    for fields in rows(path):
        if fields[0] != mode or fields[1] != word:
            continue
        items = [i for i in fields[3].split(' ') if i]
        print('> %s   (java original, %s)' % (word, mode))
        # The Java list can repeat a sequence; the IME de-duplicates by text,
        # so both numbers are printed to make a count mismatch explainable.
        seen = set()
        unique = []
        for item in items:
            if item not in seen:
                seen.add(item)
                unique.append(item)
        for n, item in enumerate(unique, 1):
            points = [int(p, 16) for p in item.split('.')]
            text = ''.join(chr(p) for p in points)
            codes = ' '.join('U+%04X' % p for p in points)
            print('  %d. %s  %s' % (n, text, codes))
        print('  java listed %d, %d unique (%d repeated)'
              % (len(items), len(unique), len(items) - len(unique)))
        return 0

    print('no golden row for %s / %s' % (mode, word))
    return 1


if __name__ == '__main__':
    sys.exit(main())
